using BARANG.Core.Application.Abstractions.Actors;using BARANG.Core.Application.Background;using BARANG.Core.Application.Workflow;using BARANG.Core.Domain.Files;using BARANG.Core.Infrastructure.Context;using BARANG.Core.Infrastructure.Files;using BARANG.Core.Infrastructure.Persistence;using Hangfire;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Hosting;
namespace BARANG.Core.Infrastructure.Background;
public sealed class OutboxDispatchJob(IOutboxDispatcher dispatcher){[DisableConcurrentExecution(300)]public Task<int>RunAsync(CancellationToken ct)=>dispatcher.DispatchAllAsync(ct);}
public sealed class SlaScheduler(CoreDbContext db,CompanyContext companies,CurrentActorContext actors,IWorkflowAdministration workflow):ISlaScheduler
{[DisableConcurrentExecution(300)]public async Task RunAsync(CancellationToken ct){Guid[]ids=await db.Companies.AsNoTracking().Where(x=>x.IsActive).Select(x=>x.Id).ToArrayAsync(ct);foreach(Guid id in ids){using IDisposable c=companies.BeginScope(id);using IDisposable a=actors.BeginScope(SystemActor());await workflow.EscalateOverdueAsync(ct);}}internal static ActorContext SystemActor()=>new("background.scheduler",ActorType.System,true,SourceChannel.System,userId:"00000000-0000-0000-0000-000000000099",actorUsername:"background.scheduler");}
public sealed class FileProcessingScheduler(CoreDbContext db,CompanyContext companies,CurrentActorContext actors,IFileProcessingQueue queue,BARANG.Core.Application.Abstractions.Transactions.ITransactionExecutor tx):IFileProcessingScheduler
{[DisableConcurrentExecution(300)]public async Task RunAsync(CancellationToken ct){Guid[]companiesList=await db.Companies.AsNoTracking().Where(x=>x.IsActive).Select(x=>x.Id).ToArrayAsync(ct);foreach(Guid company in companiesList){using IDisposable c=companies.BeginScope(company);using IDisposable a=actors.BeginScope(SlaScheduler.SystemActor());var result=await tx.ExecuteAsync(async t=>BARANG.Core.Domain.Common.Result.Success<IReadOnlyList<Guid>>(await db.FileProcessingJobs.Where(x=>x.Status==FileProcessingStatus.Pending).OrderBy(x=>x.RequestedAtUtc).Select(x=>x.FileVersionId).Take(100).ToListAsync(t)),ct);if(result.IsFailure)continue;foreach(Guid version in result.Value)queue.Enqueue(company,version);}}}
internal sealed class BackgroundRecurringRegistrar(IRecurringJobManager jobs):IHostedService
{public Task StartAsync(CancellationToken ct){jobs.AddOrUpdate<OutboxDispatchJob>("barang-outbox-dispatch",x=>x.RunAsync(CancellationToken.None),"*/1 * * * *");jobs.AddOrUpdate<SlaScheduler>("barang-workflow-sla",x=>x.RunAsync(CancellationToken.None),"*/1 * * * *");jobs.AddOrUpdate<FileProcessingScheduler>("barang-file-processing",x=>x.RunAsync(CancellationToken.None),"*/1 * * * *");return Task.CompletedTask;}public Task StopAsync(CancellationToken ct)=>Task.CompletedTask;}
